def can_be_purchased(n, coins):
    """Returns True if n cents can be purchased using the given coins."""
    for i in range(n // 15 + 1):
        for j in range(n // 10 + 1):
            for k in range(n // 6 + 1):
                if 15 * i + 10 * j + 6 * k == n:
                    return True
    return False

def find_most_expensive_value(coins):
    """Finds the value in cents of the most expensive item that cannot be purchased using the given coins."""
    n = 1
    while True:
        if not can_be_purchased(n, coins):
            return n
        n += 1

coins = [6, 10, 15]
x = find_most_expensive_value(coins)
sum_of_digits = sum(int(digit) for digit in str(x))
print((x, sum_of_digits))
