import itertools
import math

# Function to compute prime factorization
def prime_factors(n):
    factors = {}
    # Factor out the 2s
    while n % 2 == 0:
        if 2 in factors:
            factors[2] += 1
        else:
            factors[2] = 1
        n = n // 2
    # Factor out other primes
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n = n // i
    if n > 2:
        factors[n] = 1
    return factors

# Generate all possible dice combinations
dice_faces = [1, 2, 3, 4, 5, 6]
possible_products = set()

# Function to compute product from a dice combination
def compute_product(dice_combination):
    prime_factorization = {}
    for d in dice_combination:
        if d == 1:
            return 1
        else:
            factors = prime_factors(d)
            for prime, exp in factors.items():
                if prime in prime_factorization:
                    prime_factorization[prime] += exp
                else:
                    prime_factorization[prime] = exp
    product = 1
    for prime, exp in prime_factorization.items():
        product *= prime ** exp
    return product

# Check combinations for n = 4
# This just selects all dice combinations for n = 4 and checks products
combinations_n4 = list(itertools.product(dice_faces, repeat=4))
products = set()
for combo in combinations_n4:
    product = compute_product(combo)
    if product not in products:
        products.add(product)

# Output the number of unique products for n = 4
print((len(products), products))
